with scored as (select *, last_value(rating, true) over (partition by country order by rating, id rows between unbounded preceding and current row) as last_known_rating, row_number() over (partition by country order by rating, id) as event_seq, sum(rating) over (partition by country order by rating, id rows between unbounded preceding and current row) as running_rating, avg(rating) over (partition by city order by rating, id rows between 5 preceding and current row) as rating_avg_5, sum(rating) over (order by rating, id rows between unbounded preceding and current row) as cumulative_rating from suppliers) select city, country, count(*) filter (where country = 'JP') as jp_rows, round(avg(event_seq), 2) as avg_event_seq, round(sum(cumulative_rating) / nullif(count(case when city = 'Berlin' then 1 end), 0), 2) as cumulative_rating_per_berlin, grouping_id() as grouping_level from scored group by cube (city, country);
